import Link from 'next/link';import {requireVendor} from '@/lib/auth/vendor';import {getVendorDashboard,fcfa,vendorStatusLabels} from '@/services/vendor-dashboard';import {toggleRestaurantPause} from '@/app/vendor/actions';import {SubmitButton,VendorFlash} from '@/components/vendor-forms';
export default async function VendorDashboardPage({searchParams}:{searchParams:Promise<{error?:string}>}){const[{error},context]=await Promise.all([searchParams,requireVendor()]);const data=await getVendorDashboard(context.restaurant!.id);return <><VendorFlash message={error==='permissions'?'Cette action est réservée au propriétaire ou au responsable.':undefined}/><div className="vendor-page-head"><div><p className="section-kicker">Aujourd’hui</p><h1>Bonjour{context.displayName?` ${context.displayName}`:''}</h1><p>Voici l’essentiel pour votre restaurant.</p></div><div className="vendor-head-actions"><Link href="/vendor/products/new" className="btn btn-dark">+ Ajouter un produit</Link><Link href="/vendor/orders" className="btn btn-outline">Voir les commandes</Link></div></div><section className="vendor-metrics"><article><span>Commandes aujourd’hui</span><strong>{data.ordersToday}</strong></article><article><span>Chiffre d’affaires</span><strong>{fcfa(data.revenueToday)}</strong></article><article><span>À préparer</span><strong>{data.toPrepare}</strong></article><article><span>Prêtes</span><strong>{data.ready}</strong></article><article><span>Produits indisponibles</span><strong>{data.unavailableProducts}</strong></article></section><div className="vendor-dashboard-grid"><section className="vendor-card"><div className="card-head"><h2>Commandes récentes</h2><Link href="/vendor/orders">Tout voir</Link></div>{data.recentOrders.length?<div className="vendor-order-list">{data.recentOrders.map(row=>{const order=row.order as unknown as Record<string,unknown>;return <Link href={`/vendor/orders/${row.id}`} key={row.id}><span><strong>{String(order?.reference??'Commande')}</strong><small>{String(order?.customer_name??'Client')} · {String(order?.fulfillment)==='pickup'?'Retrait':'Livraison'}</small></span><span><b>{fcfa(row.subtotal)}</b><small>{vendorStatusLabels[row.status]}</small></span></Link>})}</div>:<div className="vendor-empty"><strong>Aucune commande pour le moment.</strong><p>Les nouvelles commandes apparaîtront ici.</p></div>}</section><aside className="vendor-card vendor-quick"><h2>Actions rapides</h2>{context.canManage?<><form action={toggleRestaurantPause}><SubmitButton className="btn btn-outline" confirmMessage={context.restaurant!.operatingStatus==='paused'?'Reprendre les commandes maintenant ?':'Mettre le restaurant en pause ?'}>{context.restaurant!.operatingStatus==='paused'?'Reprendre les commandes':'Mettre en pause'}</SubmitButton></form><Link href="/vendor/restaurant">Modifier le restaurant</Link></>:<p>Vous pouvez suivre et mettre à jour les commandes.</p>}</aside></div></>}
